        {
          "type": "improvement",
          "priority": "low",
          "timestamp": "2026-06-26T13:30:13Z",
          "note": "notes-collected.test.mjs hangs (process does not exit) — pre-existing issue, file not modified by WP-008 (git status and git diff both clean for this file). Likely a dangling async handle or timer stub in the test setup. Should be investigated independently."
        }
      ]
    }
