129	/**
130	 * Render the Settings view into a fresh container and wait for all async
131	 * operations (API fetches + DOM construction) to complete.
132	 *
133	 * @returns {Promise<HTMLElement>} The container element.
134	 */
135	async function renderAndWait() {
136	    const container = document.createElement('div');
137	    container.id = 'app';
138	    document.body.appendChild(container);
139	    renderSettings(container, {});
140	    // Flush micro-tasks and timers to allow async table load to complete.
141	    await new Promise((resolve) => setTimeout(resolve, 0));
142	    return container;
143	}
